def merge_cards(cards: list[list[str]]) -> list[list[str]]:
    parent, owner = {}, {}                   # email -> parent email, email -> name

    def find(x: str) -> str:
        while parent[x] != x:
            parent[x] = parent[parent[x]]    # path halving
            x = parent[x]
        return x

    for name, *emails in cards:
        for email in emails:
            parent.setdefault(email, email)
            owner[email] = name
            parent[find(email)] = find(emails[0])    # link roots, never the emails themselves
    groups = {}
    for email in parent:
        groups.setdefault(find(email), []).append(email)
    return [[owner[root], *sorted(members)] for root, members in groups.items()]

perf.naive:
def merge_cards(cards: list[list[str]]) -> list[list[str]]:
    groups = [[name, set(emails)] for name, *emails in cards]
    merged = True
    while merged:                            # merge any two groups sharing an email, start over
        merged = False
        for i in range(len(groups)):
            for j in range(i + 1, len(groups)):
                if groups[i][1] & groups[j][1]:
                    groups[i][1] |= groups.pop(j)[1]
                    merged = True
                    break
            if merged:
                break
    return [[name, *sorted(emails)] for name, emails in groups]
